     1	package hotel.reservations;
     2	
     3	import hotel.documents.ReservationReceipt;
     4	import hotel.messages.EmailSender;
     5	import hotel.rooms.Room;
     6	import hotel.rooms.Rooms;
     7	import java.math.BigDecimal;
     8	import java.util.List;
     9	
    10	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    11	public final class ReservationService {
    12	
    13	    static final String HOTEL_NAME = "Pousada Maré Alta";
    14	
    15	    private final Rooms rooms;
    16	    private final ReservationStore store;
    17	    private final PriceCalculator priceCalculator;
    18	    private final EmailSender emailSender;
    19	    private final List<ReservationListener> listeners;
    20	
    21	    public ReservationService(
    22	            Rooms rooms,
    23	            ReservationStore store,
    24	            PriceCalculator priceCalculator,
    25	            EmailSender emailSender,
    26	            List<ReservationListener> listeners) {
    27	        this.rooms = rooms;
    28	        this.store = store;
    29	        this.priceCalculator = priceCalculator;
    30	        this.emailSender = emailSender;
    31	        this.listeners = List.copyOf(listeners);
    32	    }
    33	
    34	    public synchronized Reservation create(NewReservation request) {
    35	        if (!request.checkOut().isAfter(request.checkIn())) {
    36	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    37	        }
    38	        if (request.guests() < 1) {
    39	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    40	        }
    41	        Room room = rooms.find(request.roomNumber())
    42	                .orElseThrow(() -> new HotelException(
    43	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    44	        if (request.guests() > room.capacity()) {
    45	            throw new HotelException(
    46	                    ErrorCode.CAPACITY_EXCEEDED,
    47	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    48	        }
    49	        boolean roomTaken = store.all().stream()
    50	                .filter(existing -> existing.status() != ReservationStatus.CANCELLED)
    51	                .anyMatch(existing -> existing.overlaps(room.number(), request.checkIn(), request.checkOut()));
    52	        if (roomTaken) {
    53	            throw new HotelException(
    54	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    55	        }
    56	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
    57	        Reservation reservation = new Reservation(store.nextId(), request, price);
    58	        store.save(reservation);
    59	        return reservation;
    60	    }
    61	
    62	    public Reservation find(long reservationId) {
    63	        return store.find(reservationId)
    64	                .orElseThrow(() -> new HotelException(
    65	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    66	    }
    67	
    68	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    69	    public synchronized Reservation confirm(long reservationId) {
    70	        Reservation reservation = find(reservationId);
    71	        if (reservation.status() != ReservationStatus.PENDING) {
    72	            throw notAllowed(reservation, "confirm");
    73	        }
    74	        reservation.confirmPayment();
    75	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
    76	        emailSender.send(
    77	                reservation.guest().email(),
    78	                "Reserva confirmada - " + HOTEL_NAME,
    79	                confirmationEmailBody(reservation, receipt));
    80	        publish(new ReservationEvent.Confirmed(reservation));
    81	        return reservation;
    82	    }
    83	
    84	    /**
    85	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    86	     * reservation was never paid, so nothing comes back).
    87	     */
    88	    public synchronized Reservation cancel(long reservationId) {
    89	        Reservation reservation = find(reservationId);
    90	        if (reservation.status() != ReservationStatus.PENDING
    91	                && reservation.status() != ReservationStatus.CONFIRMED) {
    92	            throw notAllowed(reservation, "cancel");
    93	        }
    94	        BigDecimal refund = switch (reservation.ratePlan()) {
    95	            case STANDARD -> reservation.amountPaid();
    96	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
    97	        };
    98	        boolean wasConfirmed = reservation.status() == ReservationStatus.CONFIRMED;
    99	        reservation.cancel(refund);
   100	        publish(new ReservationEvent.Cancelled(reservation, wasConfirmed));
   101	        return reservation;
   102	    }
   103	
   104	    public synchronized Reservation checkIn(long reservationId) {
   105	        Reservation reservation = find(reservationId);
   106	        if (reservation.status() != ReservationStatus.CONFIRMED) {
   107	            throw notAllowed(reservation, "check in");
   108	        }
   109	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   110	        return reservation;
   111	    }
   112	
   113	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   114	    public synchronized ReservationReceipt checkOut(long reservationId) {
   115	        Reservation reservation = find(reservationId);
   116	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   117	            throw notAllowed(reservation, "check out");
   118	        }
   119	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   120	        return new ReservationReceipt(reservation, roomOf(reservation));
   121	    }
   122	
   123	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   124	    public ReservationReceipt receiptCopy(long reservationId) {
   125	        Reservation reservation = find(reservationId);
   126	        if (!reservation.isPaid()) {
   127	            throw notAllowed(reservation, "issue a receipt for");
   128	        }
   129	        return new ReservationReceipt(reservation, roomOf(reservation));
   130	    }
   131	
   132	    private void publish(ReservationEvent event) {
   133	        listeners.forEach(listener -> listener.on(event));
   134	    }
   135	
   136	    private Room roomOf(Reservation reservation) {
   137	        return rooms.find(reservation.roomNumber()).orElseThrow();
   138	    }
   139	
   140	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   141	        return "Olá, " + reservation.guest().name() + "!\n\n"
   142	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   143	                + receipt.text() + "\n"
   144	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   145	                + "Até breve!\n";
   146	    }
   147	
   148	    private static HotelException notAllowed(Reservation reservation, String operation) {
   149	        return new HotelException(
   150	                ErrorCode.OPERATION_NOT_ALLOWED,
   151	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   152	    }
   153	}
