    21	    public ReservationService(
    22	            Rooms rooms,
    23	            ReservationStore store,
    24	            PriceCalculator priceCalculator,
    25	            EmailSender emailSender,
    26	            List<ReservationListener> listeners) {
    27	        this.rooms = rooms;
    28	        this.store = store;
